const x=$input.first().json;
const s=x.sampling||{};
const ok=x.ok===true && x.status==='SM3_SCENE_AWARE_PASS' && x.version==='2.0.0' && s.sampling_mode==='ADAPTIVE_SCENE_V2' && Number(s.scene_detected_count||0)>=2 && Number(s.selected_frame_count||0)>=4;
if(!ok) throw new Error('SM3_SCENE_AWARE_ASSERT_FAILED: '+JSON.stringify(x));
return [{json:{status:'SM3_SCENE_AWARE_PASS',worker_version:x.version,sampling_mode:s.sampling_mode,scene_detected_count:s.scene_detected_count,candidate_count:s.candidate_count,selected_frame_count:s.selected_frame_count,frame_times_seconds:s.frame_times_seconds,fallback_used:s.fallback_used,contact_sheet_path:x.contact_sheet_path,contact_sheet_bytes:x.contact_sheet_bytes}}];
